#include "jerico/dock.hpp"
#include "jerico/evaluate.hpp"
#include "jerico/dock_materials.hpp"
#include "jerico/export.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <chrono>
using namespace jerico;
int main(int argc,char**argv){try{std::string out="output/preview",recipePath;int res=256;bool obj=true;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--out"&&i+1<argc)out=argv[++i];else if(a=="--recipe"&&i+1<argc)recipePath=argv[++i];else if(a=="--resolution"&&i+1<argc)res=std::stoi(argv[++i]);else if(a=="--no-obj")obj=false;else throw std::invalid_argument("arguments: --out DIR --recipe JSON --resolution N --no-obj");}Json recipe=default_dock_recipe();if(!recipePath.empty()){std::ifstream f(recipePath);f>>recipe;}auto t0=std::chrono::steady_clock::now();auto scene=build_dock(recipe);auto errors=validate_scene(scene);if(!errors.empty())throw std::runtime_error(errors.dump());errors=validate_dock(scene);if(!errors.empty())throw std::runtime_error(errors.dump());auto t1=std::chrono::steady_clock::now();scene=evaluate_scene(scene);errors=validate_scene(scene);if(!errors.empty())throw std::runtime_error(errors.dump());auto t2=std::chrono::steady_clock::now();std::filesystem::create_directories(out);bake_dock_materials(scene,(std::filesystem::path(out)/"textures").string(),res);auto t3=std::chrono::steady_clock::now();write_glb(scene,(std::filesystem::path(out)/"dock.glb").string());if(obj)write_obj_mtl(scene,(std::filesystem::path(out)/"dock.obj").string());auto t4=std::chrono::steady_clock::now();size_t vertices=0,triangles=0;for(auto&p:scene["parts"]){vertices+=p["vertices"].size();for(auto&f:p["faces"])triangles+=f.size()-2;}auto ms=[](auto a,auto b){return std::chrono::duration<double,std::milli>(b-a).count();};Json report={{"parts",scene["parts"].size()},{"vertices",vertices},{"triangles",triangles},{"geometry_ms",ms(t0,t1)},{"evaluation_ms",ms(t1,t2)},{"bake_ms",ms(t2,t3)},{"export_ms",ms(t3,t4)},{"glb_bytes",std::filesystem::file_size(std::filesystem::path(out)/"dock.glb")},{"shared_materials",scene["metadata"]["native_material_bake"]["shared_material_count"]},{"validation_errors",errors},{"stairs",scene["metadata"].value("stairs",Json())}};std::ofstream(std::filesystem::path(out)/"recipe.json")<<recipe.dump(2);std::ofstream(std::filesystem::path(out)/"scene.json")<<scene.dump();std::ofstream(std::filesystem::path(out)/"report.json")<<report.dump(2);std::cout<<report.dump(2)<<"\n";}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
